.island-expanded {
  display: none;
  flex-direction: column;
  justify-content: space-between;
  width: 100%;
  height: 100%;
  opacity: 0;
  transition: opacity 0.3s ease 0.1s;
}

.dynamic-island.expanded .island-compact {
  display: none;
}

.dynamic-island.expanded .island-expanded {
  display: flex;
  opacity: 1;
}

.island-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.island-track-info {
  display: flex;
  align-items: center;
  gap: 12px;
  overflow: hidden;
