  height: 38px;
  border-radius: 8px;
  background: rgba(32, 239, 79, 0.1);
  border: 1px solid var(--line, #2b322d);
  display: grid;
  place-items: center;
  color: var(--green, #20ef4f);
  font-size: 16px;
  flex-shrink: 0;
}

.island-meta {
  display: flex;
  flex-direction: column;
  gap: 3px;
  overflow: hidden;
}

.island-song-title {
  font-size: 13px;
  font-weight: 500;
  color: var(--paper, #e9eee8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-family: var(--display, "Space Grotesk", sans-serif);
}

.island-artist {
  font-size: 10px;
  color: var(--muted, #858c85);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.island-close-btn {
  background: transparent;
  border: none;
  color: var(--muted, #858c85);
  cursor: pointer;
  font-size: 16px;
  padding: 4px;
  transition: color 0.2s ease;
}

.island-close-btn:hover {
  color: var(--green, #20ef4f);
}

/* Progress bar */
.island-progress-container {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 4px 0;
}

.island-progress-bar {
  width: 100%;
  height: 4px;
  background: var(--line, #2b322d);
  border-radius: 2px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.island-progress-fill {
  height: 100%;
  background: var(--green, #20ef4f);
  width: 0%;
  border-radius: 2px;
  transition: width 0.1s linear;
}

.island-time-row {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  color: var(--muted, #858c85);
}

/* Controls */
.island-controls {
  display: flex;
