.island-compact {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 100%;
  justify-content: space-between;
}

.island-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: rgba(32, 239, 79, 0.15);
