      closeBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.collapse();
      });
    }

    if (playBtn) {
      playBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.togglePlay();
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.nextTrack();
      });
    }

    if (prevBtn) {
      prevBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.prevTrack();
      });
    }

    if (progressBar) {
      progressBar.addEventListener("click", (e) => {
        e.stopPropagation();
        this.seek(e);
      });
