permissionRequest.newFileContents:
/* Dynamic Island Audio Player Styles (Inside Page Topbar) */
#dynamic-island-container {
  position: sticky;
  top: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 62px;
  padding: 12px 0;
  background: rgba(9, 11, 10, 0.9);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line, #2b322d);
  z-index: 1000;
  overflow: visible;
}

.dynamic-island {
  background: rgba(9, 11, 10, 0.94);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--line, #2b322d);
  border-radius: 28px;
  padding: 6px 14px;
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  width: 170px;
  height: 38px;
  overflow: hidden;
  transition: width 0.4s cubic-bezier(0.16, 1, 0.3, 1),
              height 0.4s cubic-bezier(0.16, 1, 0.3, 1),
              border-radius 0.4s cubic-bezier(0.16, 1, 0.3, 1),
              padding 0.4s cubic-bezier(0.16, 1, 0.3, 1),
              box-shadow 0.3s ease,
              border-color 0.3s ease;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.7), 0 0 15px rgba(32, 239, 79, 0.12);
}

.dynamic-island:hover {
  border-color: var(--green, #20ef4f);
  box-shadow: 0 4px 28px rgba(0, 0, 0, 0.8), 0 0 20px rgba(32, 239, 79, 0.25);
}

.dynamic-island.expanded {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 360px;
  height: 148px;
  border-radius: 22px;
  padding: 16px 20px;
  cursor: default;
  background: rgba(13, 16, 14, 0.98);
  border-color: var(--green, #20ef4f);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.85), 0 0 30px rgba(32, 239, 79, 0.3);
  z-index: 1000;
}

/* Compact Content */
.island-compact {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 100%;
  justify-content: space-between;
}

.island-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: rgba(32, 239, 79, 0.15);
  display: grid;
  place-items: center;
  color: var(--green, #20ef4f);
  font-size: 11px;
  flex-shrink: 0;
  animation: island-pulse 2s infinite;
}

.dynamic-island.playing .island-icon {
  animation: island-spin 4s linear infinite;
}

.island-title-marquee {
  font-size: 11px;
  color: var(--paper, #e9eee8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
  letter-spacing: 0.02em;
}

.island-wave {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 14px;
  flex-shrink: 0;
}

.island-wave span {
  width: 2px;
  background: var(--green, #20ef4f);
  border-radius: 1px;
  height: 4px;
  transition: height 0.2s ease;
}

.dynamic-island.playing .island-wave span:nth-child(1) { animation: wave 0.8s ease-in-out infinite alternate; }
.dynamic-island.playing .island-wave span:nth-child(2) { animation: wave 0.5s ease-in-out infinite alternate 0.2s; }
.dynamic-island.playing .island-wave span:nth-child(3) { animation: wave 0.7s ease-in-out infinite alternate 0.4s; }

/* Expanded Content */
.island-expanded {
  display: none;
  flex-direction: column;
  justify-content: space-between;
  width: 100%;
  height: 100%;
  opacity: 0;
  transition: opacity 0.3s ease 0.1s;
}

.dynamic-island.expanded .island-compact {
  display: none;
}

.dynamic-island.expanded .island-expanded {
  display: flex;
  opacity: 1;
}

.island-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.island-track-info {
  display: flex;
  align-items: center;
  gap: 12px;
  overflow: hidden;
}

.island-art {
  width: 38px;
  height: 38px;
  border-radius: 8px;
  background: rgba(32, 239, 79, 0.1);
  border: 1px solid var(--line, #2b322d);
  display: grid;
  place-items: center;
  color: var(--green, #20ef4f);
  font-size: 16px;
  flex-shrink: 0;
}

.island-meta {
  display: flex;
  flex-direction: column;
  gap: 3px;
  overflow: hidden;
}

.island-song-title {
  font-size: 13px;
  font-weight: 500;
  color: var(--paper, #e9eee8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-family: var(--display, "Space Grotesk", sans-serif);
}

.island-artist {
  font-size: 10px;
  color: var(--muted, #858c85);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.island-close-btn {
  background: transparent;
  border: none;
  color: var(--muted, #858c85);
  cursor: pointer;
  font-size: 16px;
  padding: 4px;
  transition: color 0.2s ease;
}

.island-close-btn:hover {
  color: var(--green, #20ef4f);
}

/* Progress bar */
.island-progress-container {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 4px 0;
}

.island-progress-bar {
  width: 100%;
  height: 4px;
  background: var(--line, #2b322d);
  border-radius: 2px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.island-progress-fill {
  height: 100%;
  background: var(--green, #20ef4f);
  width: 0%;
  border-radius: 2px;
  transition: width 0.1s linear;
}

.island-time-row {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  color: var(--muted, #858c85);
}

/* Controls */
.island-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
}

.island-btn {
  background: transparent;
  border: none;
  color: var(--paper, #e9eee8);
  cursor: pointer;
  font-size: 14px;
  padding: 4px;
  transition: color 0.2s ease, transform 0.1s ease;
  display: grid;
  place-items: center;
}

.island-btn:hover {
  color: var(--green, #20ef4f);
  transform: scale(1.1);
}

.island-btn-play {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--green, #20ef4f);
  color: var(--ink, #090b0a);
  font-size: 13px;
  box-shadow: 0 0 10px rgba(32, 239, 79, 0.4);
}

.island-btn-play:hover {
  background: #25ff56;
  color: var(--ink, #090b0a);
  transform: scale(1.05);
}

@keyframes wave {
  0% { height: 4px; }
  100% { height: 14px; }
}

@keyframes island-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

@keyframes island-spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

