// Dynamic Island Audio Player Module
export const DynamicIslandPlayer = {
  tracks: [
    {
      title: "Cybernetic Dream",
      artist: "V1R3 // Synthwave",
      url: "https://cdn.pixabay.com/download/audio/2022/05/27/audio_1808fbf756.mp3?filename=synthwave-80s-110055.mp3"
    },
    {
      title: "Neural Lofi Beats",
      artist: "V1R3 // Chill Hop",
      url: "https://cdn.pixabay.com/download/audio/2022/01/18/audio_d0a13f69d2.mp3?filename=lofi-study-112191.mp3"
    },
    {
      title: "Terminal Ambient 2077",
      artist: "V1R3 // Darkspace",
      url: "https://cdn.pixabay.com/download/audio/2022/10/14/audio_993dafb1f2.mp3?filename=chill-drone-121307.mp3"
    }
  ],
  currentIndex: 0,
  isPlaying: false,
  audio: null,
  isExpanded: false,

  init() {
    if (document.getElementById("dynamic-island-container")) return;
    this.injectStyles();
    this.render();
    this.setupAudio();
    this.setupMediaSession();
    this.bindEvents();
  },

  injectStyles() {
    if (document.querySelector('link[href*="dynamicIsland.css"]')) return;
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = "assets/functions/dynamicIsland/dynamicIsland.css";
    document.head.appendChild(link);
  },

  render() {
    const pageShell = document.querySelector(".page-shell");
    if (!pageShell) return;
    if (document.getElementById("dynamic-island-container")) return;
    const container = document.createElement("div");
    container.id = "dynamic-island-container";
    container.innerHTML = `
      <div id="dynamic-island" class="dynamic-island" role="region" aria-label="Reproductor de música Dynamic Island">
        <!-- Compact State -->
        <div class="island-compact">
          <div class="island-icon" aria-hidden="true">♫</div>
          <div class="island-title-marquee" id="island-compact-title">Cybernetic Dream</div>
          <div class="island-wave" aria-hidden="true">
            <span></span><span></span><span></span>
          </div>
        </div>

        <!-- Expanded State -->
        <div class="island-expanded">
          <div class="island-header">
            <div class="island-track-info">
              <div class="island-art" aria-hidden="true">⚡</div>
              <div class="island-meta">
                <div class="island-song-title" id="island-song-title">Cybernetic Dream</div>
                <div class="island-artist" id="island-artist">V1R3 // Synthwave</div>
              </div>
            </div>
            <button class="island-close-btn" id="island-close-btn" title="Minimizar" aria-label="Minimizar reproductor">×</button>
          </div>

          <div class="island-progress-container">
            <div class="island-progress-bar" id="island-progress-bar">
              <div class="island-progress-fill" id="island-progress-fill"></div>
            </div>
            <div class="island-time-row">
              <span id="island-current-time">0:00</span>
              <span id="island-total-time">0:00</span>
            </div>
          </div>

          <div class="island-controls">
            <button class="island-btn" id="island-prev-btn" title="Anterior" aria-label="Pista anterior">⏮</button>
            <button class="island-btn island-btn-play" id="island-play-btn" title="Reproducir / Pausar" aria-label="Reproducir o Pausar">▶</button>
            <button class="island-btn" id="island-next-btn" title="Siguiente" aria-label="Siguiente pista">⏭</button>
          </div>
        </div>
      </div>
    `;
    const stage = document.getElementById("stage");
    if (stage) {
      stage.prepend(container);
    }
  },

  setupAudio() {
    this.audio = new Audio();
    this.audio.preload = "metadata";
    this.loadTrack(this.currentIndex);

    this.audio.addEventListener("timeupdate", () => {
      if (!this.audio.duration) return;
      const progressPercent = (this.audio.currentTime / this.audio.duration) * 100;
      const fill = document.getElementById("island-progress-fill");
      if (fill) fill.style.width = `${progressPercent}%`;

      const currTimeEl = document.getElementById("island-current-time");
      if (currTimeEl) currTimeEl.textContent = this.formatTime(this.audio.currentTime);
    });

    this.audio.addEventListener("loadedmetadata", () => {
      const totalTimeEl = document.getElementById("island-total-time");
      if (totalTimeEl) totalTimeEl.textContent = this.formatTime(this.audio.duration);
    });

    this.audio.addEventListener("ended", () => {
      this.nextTrack();
    });
  },

  loadTrack(index) {
    this.currentIndex = index;
    const track = this.tracks[index];
    this.audio.src = track.url;

    const compactTitle = document.getElementById("island-compact-title");
    const songTitle = document.getElementById("island-song-title");
    const artistEl = document.getElementById("island-artist");

    if (compactTitle) compactTitle.textContent = track.title;
    if (songTitle) songTitle.textContent = track.title;
    if (artistEl) artistEl.textContent = track.artist;

    this.updateMediaSessionMetadata(track);
  },

  setupMediaSession() {
    if (!('mediaSession' in navigator)) return;
    navigator.mediaSession.setActionHandler('play', () => this.play());
    navigator.mediaSession.setActionHandler('pause', () => this.pause());
    navigator.mediaSession.setActionHandler('previoustrack', () => this.prevTrack());
    navigator.mediaSession.setActionHandler('nexttrack', () => this.nextTrack());
  },

  updateMediaSessionMetadata(track) {
    if (!('mediaSession' in navigator)) return;
    navigator.mediaSession.metadata = new MediaMetadata({
      title: track.title,
      artist: track.artist,
      album: 'V1R3 Portfolio Stream',
      artwork: [
        { src: 'assets/favicon.svg', sizes: '96x96', type: 'image/svg+xml' }
      ]
    });
  },

  togglePlay() {
    if (this.isPlaying) {
      this.pause();
    } else {
      this.play();
    }
  },

  play() {
    this.audio.play().then(() => {
      this.isPlaying = true;
      const island = document.getElementById("dynamic-island");
      const playBtn = document.getElementById("island-play-btn");
      if (island) island.classList.add("playing");
      if (playBtn) playBtn.textContent = "⏸";
    }).catch(err => {
      console.warn("Audio playback prevented or failed:", err);
    });
  },

  pause() {
    this.audio.pause();
    this.isPlaying = false;
    const island = document.getElementById("dynamic-island");
    const playBtn = document.getElementById("island-play-btn");
    if (island) island.classList.remove("playing");
    if (playBtn) playBtn.textContent = "▶";
  },

  nextTrack() {
    const nextIdx = (this.currentIndex + 1) % this.tracks.length;
    this.loadTrack(nextIdx);
    if (this.isPlaying) this.play();
  },

  prevTrack() {
    const prevIdx = (this.currentIndex - 1 + this.tracks.length) % this.tracks.length;
    this.loadTrack(prevIdx);
    if (this.isPlaying) this.play();
  },

  seek(e) {
    const bar = document.getElementById("island-progress-bar");
    if (!bar || !this.audio.duration) return;
    const rect = bar.getBoundingClientRect();
    const pos = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    this.audio.currentTime = pos * this.audio.duration;
  },

  formatTime(secs) {
    if (isNaN(secs)) return "0:00";
    const mins = Math.floor(secs / 60);
    const remaining = Math.floor(secs % 60);
    return `${mins}:${remaining < 10 ? '0' : ''}${remaining}`;
  },

  expand() {
    this.isExpanded = true;
    const island = document.getElementById("dynamic-island");
    if (island) island.classList.add("expanded");
  },

  collapse() {
    this.isExpanded = false;
    const island = document.getElementById("dynamic-island");
    if (island) island.classList.remove("expanded");
  },

  bindEvents() {
    const island = document.getElementById("dynamic-island");
    const closeBtn = document.getElementById("island-close-btn");
    const playBtn = document.getElementById("island-play-btn");
    const nextBtn = document.getElementById("island-next-btn");
    const prevBtn = document.getElementById("island-prev-btn");
    const progressBar = document.getElementById("island-progress-bar");

    if (island) {
      island.addEventListener("click", (e) => {
        if (!this.isExpanded && !e.target.closest("button")) {
          this.expand();
        }
      });
    }

    if (closeBtn) {
      closeBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.collapse();
      });
    }

    if (playBtn) {
      playBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.togglePlay();
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.nextTrack();
      });
    }

    if (prevBtn) {
      prevBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.prevTrack();
      });
    }

    if (progressBar) {
      progressBar.addEventListener("click", (e) => {
        e.stopPropagation();
        this.seek(e);
      });
    }

    // Collapse when clicking outside
    document.addEventListener("click", (e) => {
      const container = document.getElementById("dynamic-island-container");
      if (this.isExpanded && container && !container.contains(e.target)) {
        this.collapse();
      }
    });
  }
};

// Auto-initialize on load
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", () => DynamicIslandPlayer.init());
} else {
  DynamicIslandPlayer.init();
}

