  flex-direction: column;
  gap: 3px;
  overflow: hidden;
}

.island-song-title {
  font-size: 13px;
  font-weight: 500;
  color: var(--paper, #e9eee8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-family: var(--display, "Space Grotesk", sans-serif);
}

.island-artist {
  font-size: 10px;
  color: var(--muted, #858c85);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

