.island-progress-container {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 4px 0;
}

.island-progress-bar {
  width: 100%;
  height: 4px;
  background: var(--line, #2b322d);
  border-radius: 2px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.island-progress-fill {
  height: 100%;
  background: var(--green, #20ef4f);
  width: 0%;
  border-radius: 2px;
  transition: width 0.1s linear;
}

.island-time-row {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  color: var(--muted, #858c85);
}

/* Controls */
.island-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
}

.island-btn {
  background: transparent;
  border: none;
  color: var(--paper, #e9eee8);
  cursor: pointer;
  font-size: 14px;
  padding: 4px;
  transition: color 0.2s ease, transform 0.1s ease;
  display: grid;
  place-items: center;
}

.island-btn:hover {
  color: var(--green, #20ef4f);
  transform: scale(1.1);
}

.island-btn-play {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--green, #20ef4f);
  color: var(--ink, #090b0a);
  font-size: 13px;
  box-shadow: 0 0 10px rgba(32, 239, 79, 0.4);
}

.island-btn-play:hover {
  background: #25ff56;
  color: var(--ink, #090b0a);
  transform: scale(1.05);
}

@keyframes wave {
  0% { height: 4px; }
  100% { height: 14px; }
}

@keyframes island-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

@keyframes island-spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

