      closeBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.collapse();
      });
    }

    if (playBtn) {
      playBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.togglePlay();
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.nextTrack();
      });
    }

