      });
    }

    if (prevBtn) {
      prevBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.prevTrack();
      });
    }

    if (progressBar) {
      progressBar.addEventListener("click", (e) => {
        e.stopPropagation();
        this.seek(e);
      });
    }

