      artwork: [
        { src: 'assets/favicon.svg', sizes: '96x96', type: 'image/svg+xml' }
      ]
    });
  },

  togglePlay() {
    if (this.isPlaying) {
      this.pause();
    } else {
      this.play();
    }
  },

  play() {
    this.audio.play().then(() => {
      this.isPlaying = true;
